from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
import sys,json,difflib
sys.path.insert(0,'/Users/admin/src/light-cljs/tests/reference/compiler-language')
import sci_originals_after190 as proof
import sci_originals_after190_candidates as current
import sci_execution as sci
root=Path('/private/tmp/light-cljs-125-record-inspection-after190-v1')
before=proof.snapshot();programs=current.reference_execution_binding()['programs']
def replay(kind):
 original=root/kind/'execution'; rebuilt=root/(kind+'-independent-location-replay')
 command=proof.checked_location_compile(original,rebuilt,kind,programs)
 a=proof.compiled_pin_units(original);b=proof.compiled_pin_units(rebuilt)
 differences={name:{'original_sha256':a.get(name),'independent_sha256':b.get(name),'diff':''.join(difflib.unified_diff((original/name).read_text().splitlines(True),(rebuilt/name).read_text().splitlines(True),fromfile=str(original/name),tofile=str(rebuilt/name)))} for name in sorted(set(a)|set(b)) if a.get(name)!=b.get(name)}
 print(kind, 'byte-identical' if not differences else list(differences),flush=True)
 return {'command':command,'original_emitted_units_sha256':a,'independent_emitted_units_sha256':b,'differences':differences}
with ThreadPoolExecutor(max_workers=2) as pool:
 tasks={kind:pool.submit(replay,kind) for kind in ('release','checkout')}
 evidence={kind:future.result() for kind,future in tasks.items()}
if before!=proof.snapshot():raise ValueError('Inspection snapshot drift')
receipt={'schema_version':1,'scope':'Read-only emitted-unit replay diagnostic only; no source acceptance/credit','original_semantic_pass_credit':0,'snapshot':before,'reference_execution_binding':current.reference_execution_binding(),'script_sha256':sci.digest(Path(__file__).read_bytes()),'evidence':evidence}
(root/'replay-evidence.json').write_text(json.dumps(receipt,indent=2)+'\n')
